import {booked} from './payments';

const wholeKey=(line:string)=>`payment:${line}`;
const partPrefix=(line:string)=>`${wholeKey(line)}:part:`;

function hasBooking(line:string){
  const prefix=partPrefix(line);
  return booked.has(wholeKey(line)) || [...booked.keys()].some(key=>key.startsWith(prefix));
}

export function splitCheckout(line:string,parts:number[]){
  if(hasBooking(line))return {status:'already-booked'};
  parts.forEach((cents,i)=>booked.set(`${partPrefix(line)}${i}`,cents));
  return {status:'booked'};
}

export function wholeCheckout(line:string,cents:number){
  if(hasBooking(line))return {status:'already-booked'};
  booked.set(wholeKey(line),cents);
  return {status:'booked'};
}

export function reclaimReservation(line:string){return !hasBooking(line);}

